      const isSelected=selected===target,d=this.sim.distance(target);if(!isSelected&&(d>2400||target.kind==='ore'))continue;if(target.kind==='trader'&&!isSelected&&civilianCount++>=4)continue;
      let p=view.project(target.pos),off=p.z>1||p.z< -1||p.x<25||p.x>width-25||p.y<68||p.y>height-40;
      if(off&&!isSelected)continue;
