      if(off){let dx=p.x-width/2,dy=p.y-height/2;if(p.z>1){dx=-dx;dy=-dy;}if(!dx&&!dy)dy=-1;const extentX=width/2-30,extentY=height/2-90,t=Math.min(extentX/Math.max(.001,Math.abs(dx)),extentY/Math.max(.001,Math.abs(dy)));p={x:width/2+dx*t,y:height/2+dy*t};angle=Math.atan2(dy,dx)*180/Math.PI;}
