      marker.className='marker'+(isSelected?' selected':'')+(target.kind==='pirate'?' hostile':'')+(target.kind==='ore'?' ore':'')+(target.kind==='trader'?' civilian':'')+(off?' offscreen':'');marker.style.left=p.x+'px';marker.style.top=p.y+'px';marker.setAttribute('aria-label','Target '+target.name+' at '+distance(d));
      const symbol=marker.firstElementChild;symbol.textContent=off?'›':target.kind==='station'?'⌑':target.kind==='pirate'?'◇':target.kind==='patrol'?'△':target.kind==='trader'?'▱':target.kind==='ore'?'⬡':'◈';symbol.style.transform=off?`rotate(${angle}deg)`:'';
      marker.children[1].textContent=target.name;marker.children[2].textContent=distance(d);
